export const meta = {
  name: 'preship-audit-phase-60',
  description: 'Pre-ship parallel audit of phase 60 strict IPNS cutover: simplify, adversarial strict-invariant security hunt, cross-layer consistency, SDK-E2E readiness — with adversarial verification',
  phases: [
    { title: 'Audit' },
    { title: 'Verify' },
  ],
}

const BASE = 'a93e3ad1ccdedaeda8ce22a44298f5aeccca6b21'
const HEAD_BRANCH = 'feat/ipns-verification-cross-layer-closeout-desktop-and-api'

const FINDINGS_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['summary', 'findings'],
  properties: {
    summary: { type: 'string' },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['title', 'file', 'severity', 'in_scope', 'detail', 'recommendation'],
        properties: {
          title: { type: 'string' },
          file: { type: 'string', description: 'path:line or path' },
          severity: { type: 'string', enum: ['blocker', 'major', 'minor', 'nit'] },
          in_scope: { type: 'boolean', description: 'true = in scope for the phase 60 strict-cutover goal AND low-risk to fix now; false = pre-existing/out-of-domain/risky -> defer as todo' },
          detail: { type: 'string' },
          recommendation: { type: 'string' },
        },
      },
    },
  },
}

const READINESS_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['summary', 'prereqs', 'run_command', 'risk_notes'],
  properties: {
    summary: { type: 'string' },
    prereqs: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['name', 'port', 'up'],
        properties: { name: { type: 'string' }, port: { type: 'string' }, up: { type: 'boolean' } },
      },
    },
    run_command: { type: 'string' },
    risk_notes: { type: 'string' },
  },
}

phase('Audit')

const simplifyPrompt = `You are reviewing the diff of phase 60 (strict IPNS verification cross-layer cutover) BEFORE shipping a PR.
Run: \`git -C /Users/myankelev/Code/random/cipher-box diff ${BASE}..HEAD --stat\` then read the actual diffs of the changed source files (NOT the .planning/ docs).
Focus ONLY on quality cleanups: over-engineering, duplicated logic across the Rust/TS strict-verify paths, dead code left after the Legacy removal, leftover commented-out blocks, unnecessary complexity in the new verify-cache or EOL/expiry code.
This is QUALITY only — do NOT hunt for correctness bugs (a separate agent does that).
For each finding set in_scope=true only if it is a small, safe cleanup directly on phase-60 code; set in_scope=false for pre-existing or risky/large refactors.
Be precise with file:line. If the diff is clean, return an empty findings array with a summary saying so.`

const securityPrompt = `You are an adversarial security reviewer doing a PRE-SHIP hunt on phase 60 (strict fail-closed IPNS verification cutover) in /Users/myankelev/Code/random/cipher-box.
The phase's WHOLE POINT is that there is NO surviving non-strict path. Your job: try hard to find ONE that survived. Use grep/read across Rust (crates/api-client, crates/core, crates/fuse, crates/sdk, apps/desktop/src-tauri), TS (packages/sdk-core), and API (apps/api/src/ipns).
Specifically hunt for ALL of:
1. Any residual degraded/legacy acceptance: grep for 'Legacy', 'legacy', 'degraded', 'fallback' in resolve/verify paths; any else-branch that accepts a record lacking signature fields.
2. Any first-publish SKEW allowance still alive: a resolve that accepts embedded_seq != response_seq (e.g. seq==0 && resp==1 style), in Rust OR TS OR the API codec/service.
3. Any embedded-0 first-publish PRODUCER still emitting sequence 0 (grep for '0n' / ': 0' near publish/sequence; there were 9 producers — confirm none left at 0).
4. Any resolve path that BYPASSES the relocated chokepoint resolve_ipns_verified (raw resolve_ipns / DHT resolve without the verified wrapper) in fuse/sdk/desktop.
5. The new API verify-cache (apps/api/src/ipns/ipns-verify-cache.ts + its use in ipns.service.ts): can a cache HIT ever cause an UNVERIFIED or DIFFERENT record to be served as verified? Check the exact cache key, that recordVerified() is only called after a successful verifyIpnsRecordSignature, that the resolve/TEE-republish paths never populate or read it to skip verification, and the TTL.
6. EOL/expiry (D-07): confirm BOTH Rust (api-client ipns) and TS (sdk-core ipns) enforce validity/EOL on resolve and reject expired, with the same skew buffer.
For each issue, set severity (blocker if it lets an unverified/forgeable/embedded-0 record through) and in_scope=true (these are the phase's core goal). If you find NOTHING after a genuine hunt, return an empty findings array and say so explicitly in the summary, listing what you checked.`

const crossLayerPrompt = `You are auditing CROSS-LANGUAGE consistency for phase 60 in /Users/myankelev/Code/random/cipher-box.
The Rust verify (crates/api-client/src/ipns.rs), the TS verify (packages/sdk-core/src/ipns/index.ts resolveIpnsRecord), and the API (apps/api/src/ipns/ipns.service.ts + ipns-record.codec.ts) must implement the SAME strict semantics: absent signature fields => invalid; strict sequence equality (no skew); resolve-side EOL/expiry with the same skew buffer.
Also verify the cross-language test vector at tests/vectors/ipns/verify.json and its generator scripts/gen-ipns-verify-vectors.ts and the Rust consumer crates/fuse/tests/ipns_verify_vectors.rs: confirm legacy-absent and first-publish-skew are classified 'invalid', and that the vector was produced by the generator (not hand-edited).
Report any DIVERGENCE between the three layers (e.g. one enforces EOL but another doesn't, or skew buffers differ) as findings (in_scope=true). If fully consistent, return empty findings and say so, citing the specific lines you compared.`

const e2ePrereqPrompt = `You are checking SDK-E2E readiness for phase 60 in /Users/myankelev/Code/random/cipher-box. Do NOT run the suite.
1. Check whether each local prereq is listening: postgres 5432, kubo 5001, redis 6380, mock-ipns-routing 3001, and whether anything is on 3000 (the API port the suite hits). Use: \`lsof -nP -iTCP:<port> -sTCP:LISTEN\` for each (report up=true/false).
2. Read tests/sdk-e2e (find its package name + test files) and summarize what the suite exercises re: IPNS publish/resolve round-trip, sequencing/CAS, key lifecycle — the parts phase 60 changed.
3. Report the exact run command/env the suite needs (per the project's known recipe: SDK_E2E_API_URL, SDK_E2E_SECRET from apps/api/.env TEST_LOGIN_SECRET, THROTTLE_BYPASS_SECRET) and any risk that phase-60 strict changes could break it (e.g. tests that relied on embedded-0 first publish or legacy resolve).
Return the readiness report.`

const [simplify, security, crossLayer, e2e] = await parallel([
  () => agent(simplifyPrompt, { label: 'simplify', phase: 'Audit', schema: FINDINGS_SCHEMA, agentType: 'Explore' }),
  () => agent(securityPrompt, { label: 'security-strict-hunt', phase: 'Audit', schema: FINDINGS_SCHEMA, effort: 'high' }),
  () => agent(crossLayerPrompt, { label: 'cross-layer-consistency', phase: 'Audit', schema: FINDINGS_SCHEMA, effort: 'high' }),
  () => agent(e2ePrereqPrompt, { label: 'sdk-e2e-readiness', phase: 'Audit', schema: READINESS_SCHEMA }),
])

// Collect all in-scope, non-nit findings for adversarial verification.
const allFindings = []
for (const r of [simplify, security, crossLayer]) {
  if (r && Array.isArray(r.findings)) {
    for (const f of r.findings) allFindings.push(f)
  }
}
const toVerify = allFindings.filter(f => f && f.severity !== 'nit')

phase('Verify')

const verified = await parallel(
  toVerify.map((f, i) => () =>
    agent(
      `Adversarially verify this pre-ship finding against the ACTUAL code in /Users/myankelev/Code/random/cipher-box at branch ${HEAD_BRANCH}.
Finding: ${JSON.stringify(f)}
Read the cited file/line and surrounding context. Decide: is it REAL (the described problem actually exists in the current code) and is the severity right? For a security 'blocker', be skeptical: confirm there is a concrete path where an unverified/forgeable/embedded-0/expired record is accepted — if it actually fails closed, mark real=false. Return your verdict.`,
      {
        label: `verify:${(f.file || 'finding').split('/').pop()}-${i}`,
        phase: 'Verify',
        effort: 'high',
        schema: {
          type: 'object',
          additionalProperties: false,
          required: ['real', 'severity_confirmed', 'rationale'],
          properties: {
            real: { type: 'boolean' },
            severity_confirmed: { type: 'string', enum: ['blocker', 'major', 'minor', 'nit', 'not-real'] },
            rationale: { type: 'string' },
          },
        },
      }
    ).then(v => ({ finding: f, verdict: v }))
  )
)

const confirmed = verified.filter(Boolean).filter(v => v.verdict && v.verdict.real)

return {
  simplify_summary: simplify ? simplify.summary : null,
  security_summary: security ? security.summary : null,
  crosslayer_summary: crossLayer ? crossLayer.summary : null,
  e2e_readiness: e2e || null,
  total_findings: allFindings.length,
  confirmed_findings: confirmed.map(v => ({ ...v.finding, verdict: v.verdict })),
  unconfirmed_or_rejected: verified.filter(Boolean).filter(v => !(v.verdict && v.verdict.real)).map(v => ({ title: v.finding.title, file: v.finding.file, reason: v.verdict ? v.verdict.rationale : 'no verdict' })),
}

