  simplify_summary: simplify ? simplify.summary : null,
  security_summary: security ? security.summary : null,
  crosslayer_summary: crossLayer ? crossLayer.summary : null,
  e2e_readiness: e2e || null,
  total_findings: allFindings.length,
  confirmed_findings: confirmed.map(v => ({ ...v.finding, verdict: v.verdict })),
  unconfirmed_or_rejected: verified.filter(Boolean).filter(v => !(v.verdict && v.verdict.real)).map(v => ({ title: v.finding.title, file: v.finding.file, reason: v.verdict ? v.verdict.rationale : 'no verdict' })),
}

