const fs=require("fs");
const cfg=JSON.parse(fs.readFileSync("release-please-config.json","utf8"));
const {execSync}=require("child_process");
const mainManifest=JSON.parse(execSync("git show origin/main:.release-please-manifest.json").toString());
console.log("pkg | release-as(branch cfg) | main manifest | MERGE-TREE verdict");
console.log("---");
for(const [p,c] of Object.entries(cfg.packages)){
  const ra=c["release-as"];
  if(ra===undefined) continue;
  const mv=mainManifest[p];
  let verdict;
  if(mv===undefined) verdict="ok(not in manifest)";
  else if(ra===mv) verdict="*** STALE (==) ***";
  else verdict="ok ("+ra+" vs "+mv+")";
  console.log(`${p} | ${ra} | ${mv} | ${verdict}`);
}
'

