/**
 * @cipherbox/crypto
 *
 * Pure cryptographic primitives and key derivation for CipherBox.
 * Provides AES-256-GCM/CTR encryption, ECIES key wrapping, Ed25519 signing,
 * and key hierarchy management.
 *
 * Security principles:
 * - All operations use Web Crypto API or audited libraries (@noble/*, eciesjs)
 * - Error messages are generic to prevent oracle attacks
 * - Keys are Uint8Array - never convert to/from strings for sensitive data
 * - Private keys exist in memory only - never persisted to storage
 *
 * @example
 * ```typescript
 * import {
 *   generateFileKey,
 *   generateIv,
 *   encryptAesGcm,
 *   decryptAesGcm,
 *   wrapKey,
 *   unwrapKey
 * } from '@cipherbox/crypto';
 *
 * // Encrypt file content
 * const fileKey = generateFileKey();
 * const iv = generateIv();
 * const ciphertext = await encryptAesGcm(plaintext, fileKey, iv);
 *
 * // Wrap file key with user's public key
 * const wrappedKey = await wrapKey(fileKey, vaultKey.publicKey);
 *
 * // Unwrap and decrypt
 * const unwrappedKey = await unwrapKey(wrappedKey, vaultKey.privateKey);
 * const decrypted = await decryptAesGcm(ciphertext, unwrappedKey, iv);
 * ```
 */

export const CRYPTO_VERSION = '0.2.0';

// Vault IPNS key derivation (only derive-ipns remains in crypto)
export {
  deriveVaultIpnsKeypair,
  deriveVaultKeyIpnsKeypair,
  deriveByoConfigIpnsKeypair,
  deriveVaultSettingsIpnsKeypair,
} from './vault';

// Key hierarchy and derivation
export { deriveKey, deriveContextKey, generateFolderKey, type DeriveKeyParams } from './keys';

// AES-256-GCM symmetric encryption
export { encryptAesGcm, decryptAesGcm, sealAesGcm, unsealAesGcm } from './aes';

// AES-256-CTR streaming encryption (random-access decryption for media)
export { encryptAesCtr, decryptAesCtr, decryptAesCtrRange } from './aes';

// ECIES secp256k1 key wrapping
export { wrapKey, unwrapKey, reWrapKey } from './ecies';

// Ed25519 signing for IPNS
export { generateEd25519Keypair, deriveEd25519PublicKey, type Ed25519Keypair } from './ed25519';
export { signEd25519, verifyEd25519 } from './ed25519/sign';

// IPNS name derivation + record verification/parsing (pure crypto utilities,
// backed by the `ipns` package so the wire format matches record creation)
export { deriveIpnsName } from './ipns/derive-name';
export { verifyIpnsRecordSignature } from './ipns/verify-record';
export { parseIpnsRecord, type ParsedIpnsRecord } from './ipns/parse-record';

// Device identity (per-device Ed25519 keypair)
export { generateDeviceKeypair, deriveDeviceId, type DeviceKeypair } from './device';

// Utility functions (only safe public utilities)
export {
  hexToBytes,
  bytesToHex,
  concatBytes,
  clearBytes,
  clearAll,
  generateRandomBytes,
  generateFileKey,
  generateIv,
  generateCtrIv,
} from './utils';

// Types
export { CryptoError, type CryptoErrorCode, type VaultKey, type EncryptedData } from './types';

// Constants
export {
  AES_KEY_SIZE,
  AES_IV_SIZE,
  AES_TAG_SIZE,
  SECP256K1_PUBLIC_KEY_SIZE,
  SECP256K1_PRIVATE_KEY_SIZE,
  ECIES_MIN_CIPHERTEXT_SIZE,
  AES_GCM_ALGORITHM,
  AES_CTR_IV_SIZE,
  AES_CTR_NONCE_SIZE,
  AES_CTR_LENGTH,
  AES_CTR_ALGORITHM,
  ED25519_PUBLIC_KEY_SIZE,
  ED25519_PRIVATE_KEY_SIZE,
  ED25519_SIGNATURE_SIZE,
} from './constants';

import { HttpException, HttpStatus, Logger } from '@nestjs/common';
import { parseIpnsRecord } from '@cipherbox/crypto';
import type { FolderIpns } from './entities/folder-ipns.entity';

export interface IpnsRecordFields {
  cid: string;
  sequenceNumber: string;
  signatureV2?: string;
  data?: string;
  pubKey?: string;
}

/**
 * Parse an IPNS record to extract CID and sequence number.
 * Backed by the `ipns` package via @cipherbox/crypto (parseIpnsRecord).
 */
export async function parseIpnsRecordBytes(
  recordBytes: Uint8Array,
  logger: Logger
): Promise<IpnsRecordFields> {
  try {
    const record = await parseIpnsRecord(recordBytes);

    // Extract CID from the Value field (format: /ipfs/<cid>)
    const valuePath = record.value;
    const cidMatch = valuePath.match(/\/ipfs\/([a-zA-Z0-9]+)/);
    if (!cidMatch) {
      logger.error('Failed to extract CID from IPNS record value');
      throw new HttpException('Invalid IPNS record format', HttpStatus.BAD_GATEWAY);
    }

    const cid = cidMatch[1];
    const sequenceNumber = String(record.sequence ?? 0n);

    // Base64-encode signature fields if present
    const signatureV2 = record.signatureV2
      ? Buffer.from(record.signatureV2).toString('base64')
      : undefined;
    const data = record.data ? Buffer.from(record.data).toString('base64') : undefined;
    const pubKey = record.pubKey ? Buffer.from(record.pubKey).toString('base64') : undefined;

    logger.debug(`Parsed IPNS record: cid=${cid}, sequenceNumber=${sequenceNumber}`);
    return { cid, sequenceNumber, signatureV2, data, pubKey };
  } catch (error) {
    if (error instanceof HttpException) {
      throw error;
    }
    logger.error(`Failed to parse IPNS record: ${error}`);
    throw new HttpException('Invalid IPNS record format', HttpStatus.BAD_GATEWAY);
  }
}

export async function parseCachedRecord(
  cached: FolderIpns | null,
  logger: Logger
): Promise<IpnsRecordFields | null> {
  if (!cached?.latestCid) {
    return null;
  }

  // D-06 (Plan 60-05): null signedRecord → return null (→ 404 to caller).
  // A row without a signed record cannot be served as authoritative; the client
  // cannot verify an unsigned CID and must not act on it.
  if (!cached.signedRecord) {
    return null;
  }

  try {
    const parsed = await parseIpnsRecordBytes(cached.signedRecord, logger);
    // D-06 (Plan 60-05): discard on CID or sequence mismatch between the signed
    // record bytes and the DB columns — a mismatch means the row is inconsistent
    // and must not be served.  Warn and return null; the caller will 404.
    if (parsed.cid !== cached.latestCid) {
      logger.warn(
        `Cached signed record CID mismatch for ${cached.ipnsName}: signedRecord=${parsed.cid}, latestCid=${cached.latestCid} — discarding cached result`
      );
      return null;
    }
    // DB columns are authoritative for sequenceNumber (upsertFolderIpns always
    // increments it, while the embedded bytes reflect the client's pre-increment value).
    //
    // The Ed25519 IPNS record's pubKey is not re-extractable from the signed bytes by
    // parseIpnsRecordBytes, so supply it from the validated publicKey column to keep the
    // cached record complete and client-verifiable. Publish enforced
    // deriveIpnsName(publicKey) === ipnsName (ipns.service.ts), and the strict client
    // re-checks that pubKey→name binding, so trusting this column is safe.
    const pubKey =
      parsed.pubKey ?? (cached.publicKey ? cached.publicKey.toString('base64') : undefined);
    // Fail closed when no pubKey can be supplied. Ed25519 records don't embed the key
    // (parsed.pubKey undefined) and the publicKey column is nullable, so a row missing
    // publicKey yields an unverifiable record; serving it would hand a strict client a CID
    // it cannot verify. Return null → the caller 404s.
    if (!pubKey) {
      logger.warn(
        `Cached signed record for ${cached.ipnsName} has no pubKey (publicKey column null) — discarding cached result`
      );
      return null;
    }
    return { ...parsed, cid: cached.latestCid, sequenceNumber: cached.sequenceNumber, pubKey };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    logger.warn(`Failed to parse cached signed record for ${cached.ipnsName}: ${message}`);
    return null;
  }
}

