export const meta = {
  name: 'triage-coderabbit-code-findings',
  description: 'Adversarially verify 5 CodeRabbit code findings on PR 555 against current code; return verdict + minimal patch or defer reason',
  phases: [{ title: 'Verify' }],
}

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['finding', 'verdict', 'reason', 'patch', 'reply'],
  properties: {
    finding: { type: 'string', description: 'short id e.g. #5-ciborium' },
    verdict: { type: 'string', enum: ['valid-fix-now', 'defer-todo', 'false-positive', 'already-ok'] },
    reason: { type: 'string', description: 'why this verdict, citing current code at HEAD' },
    patch: { type: 'string', description: 'if valid-fix-now: the exact minimal change (file + old→new). Else empty.' },
    reply: { type: 'string', description: 'one-paragraph reply to post on the review thread stating the disposition' },
  },
}

const REPO = '/Users/myankelev/Code/random/cipher-box'
const CTX = `CipherBox monorepo at ${REPO}, PR #555 (Phase 60 strict fail-closed IPNS verify cutover), branch HEAD already includes the author's fixes. Operating rule: in-scope for the phase goal AND low-risk → valid-fix-now (give the exact minimal patch); pre-existing / out-of-domain / risky-on-the-verify-path / cross-layer-heavy-lift → defer-todo; contradicts current code → false-positive; already handled → already-ok. Do NOT run builds or full test suites; read code + git only. Adversarially verify the finding against the ACTUAL current code before agreeing.`

phase('Verify')
const findings = [
  { id: '#5-ciborium', prompt: `${CTX}

FINDING (#5, Minor maintainability): "Move \`ciborium\` to [dev-dependencies]. ciborium is only used inside #[cfg(test)] in crates/api-client/src/ipns.rs, so it should not be a normal dependency of cipherbox-api-client." (crates/api-client/Cargo.toml:18)

VERIFY: grep every \`ciborium\` usage in crates/api-client/src (rg -n 'ciborium' crates/api-client/src). Are ALL usages inside \`#[cfg(test)]\` modules / test fns? Check whether any non-test code in api-client (e.g. bind_verified) uses ciborium directly, or whether CBOR decoding is delegated to cipherbox_core (which has its own ciborium). If truly test-only, the fix is to move \`ciborium = ...\` from [dependencies] to [dev-dependencies] in crates/api-client/Cargo.toml. Confirm the exact current Cargo.toml line and which section it's in.` },

  { id: '#6-skew-test', prompt: `${CTX}

FINDING (#6, Minor correctness): "Make the skew-buffer test assert the skew boundary. bind_verified_within_skew_buffer_returns_ok is described as '2 minutes in the past' but uses a 2099 timestamp, so it would still pass if the 5-minute buffer were removed. Factor the expiry predicate or inject now so now-120s is accepted and now-301s is rejected." (crates/api-client/src/ipns.rs:788)

VERIFY: read the test bind_verified_within_skew_buffer_returns_ok and how bind_verified computes 'now' for expiry (does it call a system clock like SystemTime::now / chrono Utc::now internally, with a 5-min/300s skew buffer?). Can the TEST construct now-relative RFC3339 timestamps (now-120s should be accepted within the 300s buffer; now-301s should be rejected) WITHOUT refactoring production code to inject a clock — i.e. does the crate already depend on chrono/time so the test can format Utc::now()-Duration? Give the exact test edit (the helper that builds the Validity timestamp + two assertions) if feasible and low-risk. If it would require injecting a clock into production verify code (risky), defer-todo instead.` },

  { id: '#7-validitytype', prompt: `${CTX}

FINDING (#7, Major security): "Bind ValidityType when accepting Validity. bind_verified treats the extracted timestamp as EOL, but decode_ipns_cbor_validity accepts Validity without requiring signed ValidityType == 0. A record with missing or non-EOL ValidityType should fail closed instead of being interpreted as EOL." (crates/core/src/ipns.rs:162)

VERIFY: read decode_ipns_cbor_validity in crates/core/src/ipns.rs and how bind_verified (crates/api-client/src/ipns.rs) uses it. Does the CBOR data include a ValidityType field, and is it currently read/checked anywhere (Rust OR the TS verifier packages/sdk-core/src/ipns/index.ts)? KEY parity question: do BOTH Rust and TS currently ignore ValidityType (=> consistent), such that enforcing it only in Rust would create a Rust-stricter-than-TS parity gap (the author previously rejected the TS-side of this for that exact reason)? Consider: the Ed25519 signature covers the whole CBOR data including ValidityType, so it's not forgeable; CipherBox only ever creates ValidityType=0 (EOL) records. Weigh whether this is in-scope low-risk vs a cross-layer (Rust+TS+vectors) hardening that is risky on a currently-green verify path. Recommend valid-fix-now ONLY if it's safe and single-layer; otherwise defer-todo with precise scope for the todo.` },

  { id: '#9-vector-lockstep', prompt: `${CTX}

FINDING (#9, Major correctness, 'Heavy lift'): "Keep vector classification in lockstep with bind_verified. The classifier in crates/fuse/tests/ipns_verify_vectors.rs mirrors strict CID/sequence binding but omits the new signed Validity expiry check. An expired vector with valid signature and matching CID/sequence would be classified 'valid' here while resolve_ipns_verified rejects it." (crates/fuse/tests/ipns_verify_vectors.rs:65; also 91-145)

VERIFY: read crates/fuse/tests/ipns_verify_vectors.rs (the classifier) and the vector file tests/vectors/ipns/verify.json. Does ANY current vector have an EXPIRED Validity with otherwise-valid sig+CID+seq (i.e. a case that would actually expose the mismatch today)? Is the omission latent (no triggering vector) or active (a vector currently mis-classified)? Assess effort: would adding the expiry check require a public/exported binding helper from cipherbox-api-client or duplicating decode_ipns_cbor_validity + RFC3339 logic in the test. Recommend: valid-fix-now only if low-risk and a current vector is actually mis-classified; else defer-todo (test-fidelity hardening) with reasoning.` },

  { id: '#11-bench-key', prompt: `${CTX}

FINDING (#11, Minor correctness): "Align the cache-hit simulation with the publish-path cache key contract. In scripts/bench-ipns-verify.ts around line 194-200 the benchmark models a signature-based key, but the publish path caches base64(recordBytes) with an empty sequence slot (see apps/api/src/ipns/ipns.service.ts and apps/api/src/ipns/ipns-verify-cache.ts). The benchmark diverges from the real D-11 cache identity." (scripts/bench-ipns-verify.ts:200)

VERIFY: read scripts/bench-ipns-verify.ts around 180-210 and the real cache key construction in apps/api/src/ipns/ipns.service.ts (the isVerified/recordVerified call — what string is the key?) and apps/api/src/ipns/ipns-verify-cache.ts (the keying). Confirm the real key is \`\${ipnsName}:\${''}:\${base64(recordBytes)}\` (empty sequence slot) vs the bench's signature-based key. This is a benchmark-only script (not a test gate, not production). Give the exact minimal edit to align the bench's simulated key with the real contract if low-risk.` },
]

const results = await parallel(findings.map(f => () => agent(f.prompt, { label: f.id, schema: SCHEMA, effort: 'high' })))
return results

